window.__POLYGON_SCRIPT_PARTS__ = window.__POLYGON_SCRIPT_PARTS__ || [];
window.__POLYGON_SCRIPT_PARTS__.push("    (() => {\n      'use strict';\n\n      const workspaceNames = {\n        'program': 'Программа',\n        'map-editor': 'Редактор карты',\n        'unit-editor': 'Редактор юнита',\n        'series': 'Серия',\n        'metrics': 'Метрики',\n        'journal': 'Журнал'\n      };\n\n      const mapSubmodeNames = {\n        field: 'Поле',\n        relief: 'Рельеф',\n        ground: 'Покрытие',\n        roads: 'Дороги',\n        buildings: 'Здания',\n        objects: 'Предметы'\n      };\n\n      const editorNames = [\n        'Граф поведения',\n        'Профили маршрута',\n        'Тактические позиции',\n        'Данные бойца',\n        'Архетипы бойцов',\n        'Профили внимания',\n        'Профили восприятия',\n        'Профили движения',\n        'Вооружение',\n        'Ранения и подавление',\n        'Профили местности',\n        'Направленный рельеф'\n      ];\n\n      const state = {\n        workspace: 'program',\n        mapSubmode: 'field',\n        inspector: 'info',\n        selectedUnitId: null,\n        simulation: 'idle',\n        elapsed: 0,\n        speed: 0.5,\n        timerId: null,\n        lastTick: 0,\n        leftWidth: Number(localStorage.getItem('polygonPrototype.leftWidth')) || 372,\n        rightWidth: Number(localStorage.getItem('polygonPrototype.rightWidth')) || 336,\n        leftCollapsed: false,\n        rightCollapsed: false,\n        mapAction: null,\n        mapActionLabel: '',\n        activeEditor: editorNames[0],\n        experiment: {\n          name: 'Новый эксперимент',\n          description: '',\n          markers: []\n        },\n        layers: {\n          grid: true,\n          labels: true,\n          routes: true,\n          cover: false\n        },\n        units: [\n          {\n            id: 'unit-1',\n            name: 'Стрелок 1',\n            short: 'С1',\n            side: 'blue',\n            sideLabel: 'Синие',\n            type: 'Стрелок',\n            state: 'Готов',\n            x: 46,\n            y: 63,\n            heading: -28,\n            health: 100,\n            suppression: 8,\n            visibility: 'Частичная',\n            weapon: 'Винтовка',\n            ammo: 45\n          },\n          {\n            id: 'unit-2',\n            name: 'Наблюдатель',\n            short: 'Н',\n            side: 'blue',\n            sideLabel: 'Синие',\n            type: 'Наблюдатель',\n            state: 'Наблюдает',\n            x: 66,\n            y: 39,\n            heading: 34,\n            health: 100,\n            suppression: 0,\n            visibility: 'Хорошая',\n            weapon: 'Пистолет',\n            ammo: 16\n          },\n          {\n            id: 'unit-3',\n            name: 'Цель 1',\n            short: 'Ц1',\n            side: 'red',\n            sideLabel: 'Красные',\n            type: 'Стрелок',\n            state: 'Ожидает',\n            x: 78,\n            y: 30,\n            heading: 152,\n            health: 100,\n            suppression: 0,\n            visibility: 'Скрыта',\n            weapon: 'Винтовка',\n            ammo: 30\n          }\n        ]\n      };\n\n      const els = {\n        mapViewport: document.getElementById('mapViewport'),\n        mapSurface: document.getElementById('mapSurface'),\n        unitLayer: document.getElementById('unitLayer'),\n        markerLayer: document.getElementById('markerLayer'),\n        workspaceTabs: document.getElementById('workspaceTabs'),\n        leftPanel: document.getElementById('leftPanel'),\n        rightPanel: document.getElementById('rightPanel'),\n        leftPanelTitle: document.getElementById('leftPanelTitle'),\n        rightPanelTitle: document.getElementById('rightPanelTitle'),\n        leftPanelContent: document.getElementById('leftPanelContent'),\n        rightPanelContent: document.getElementById('rightPanelContent'),\n        inspectorTabs: document.getElementById('inspectorTabs'),\n        collapseLeft: document.getElementById('collapseLeft'),\n        collapseRight: document.getElementById('collapseRight'),\n        leftResizer: document.getElementById('leftResizer'),\n        rightResizer: document.getElementById('rightResizer'),\n        runButton: document.getElementById('runButton'),\n        resetButton: document.getElementById('resetButton'),\n        playButton: document.getElementById('playButton'),\n        pauseButton: document.getElementById('pauseButton'),\n        speedSelect: document.getElementById('speedSelect'),\n        timerText: document.getElementById('timerText'),\n        topStatus: document.getElementById('topStatus'),\n        fileButton: document.getElementById('fileButton'),\n        editorsButton: document.getElementById('editorsButton'),\n        viewButton: document.getElementById('viewButton'),\n        viewDropdown: document.getElementById('viewDropdown'),\n        menuButton: document.getElementById('menuButton'),\n        menuDropdown: document.getElementById('menuDropdown'),\n        languageButton: document.getElementById('languageButton'),\n        contextMenu: document.getElementById('contextMenu'),\n        modalBackdrop: document.getElementById('modalBackdrop'),\n        modal: document.getElementById('modal'),\n        jsonFileInput: document.getElementById('jsonFileInput'),\n        activeAction: document.getElementById('activeAction'),\n        activeActionText: document.getElementById('activeActionText'),\n        cancelAction: document.getElementById('cancelAction'),\n        toastRegion: document.getElementById('toastRegion'),\n        experimentCaption: document.getElementById('experimentCaption'),\n        workspaceCaption: document.getElementById('workspaceCaption'),\n        selfTestResult: document.getElementById('selfTestResult')\n      };\n\n      function escapeHtml(value) {\n        return String(value ?? '')\n          .replaceAll('&', '&amp;')\n          .replaceAll('<', '&lt;')\n          .replaceAll('>', '&gt;')\n          .replaceAll('\"', '&quot;')\n          .replaceAll(\"'\", '&#039;');\n      }\n\n      function formatTime(seconds) {\n        const minutes = Math.floor(seconds / 60);\n        const rest = seconds - minutes * 60;\n        return `${String(minutes).padStart(2, '0')}:${rest.toFixed(1).padStart(4, '0')}`;\n      }\n\n      function toast(message) {\n        const item = document.createElement('div');\n        item.className = 'toast';\n        item.textContent = message;\n        els.toastRegion.append(item);\n        setTimeout(() => item.remove(), 2600);\n      }\n\n      function setSimulationState(next, options = {}) {\n        if (!['idle', 'running', 'paused'].includes(next)) return;\n        state.simulation = next;\n        els.topStatus.dataset.state = next;\n        els.runButton.setAttribute('aria-pressed', String(next === 'running'));\n        els.pauseButton.setAttribute('aria-pressed', String(next === 'paused'));\n\n        if (next === 'running') {\n          state.lastTick = performance.now();\n          if (!state.timerId) state.timerId = requestAnimationFrame(tick);\n          if (!options.silent) toast(state.elapsed > 0 ? 'Эксперимент продолжен' : 'Эксперимент запущен');\n        } else {\n          if (state.timerId) cancelAnimationFrame(state.timerId);\n          state.timerId = null;\n          if (next === 'paused' && !options.silent) toast('Эксперимент поставлен на паузу');\n        }\n      }\n\n      function tick(now) {\n        if (state.simulation !== 'running') {\n          state.timerId = null;\n          return;\n        }\n        const delta = Math.min((now - state.lastTick) / 1000, 0.1);\n        state.lastTick = now;\n        state.elapsed += delta * state.speed;\n        els.timerText.textContent = formatTime(state.elapsed);\n        state.timerId = requestAnimationFrame(tick);\n      }\n\n      function resetExperiment(options = {}) {\n        setSimulationState('idle', { silent: true });\n        state.elapsed = 0;\n        state.selectedUnitId = null;\n        state.experiment.markers = [];\n        cancelMapAction();\n        els.timerText.textContent = formatTime(0);\n        renderMarkers();\n        renderUnits();\n        renderInspector();\n        if (!options.keepMetadata) {\n          state.experiment.name = 'Новый эксперимент';\n          state.experiment.description = '';\n          els.experimentCaption.textContent = state.experiment.name;\n        }\n        if (!options.silent) toast('Эксперимент сброшен');\n      }\n\n      function setWorkspaceMode(mode, options = {}) {\n        if (!workspaceNames[mode]) return;\n        const editing = mode === 'map-editor' || mode === 'unit-editor';\n        if (editing && state.simulation === 'running') {\n          setSimulationState('paused', { silent: true });\n          if (!options.silent) toast('Для редактирования симуляция поставлена на паузу');\n        }\n        state.workspace = mode;\n        els.leftPanelTitle.textContent = workspaceNames[mode];\n        els.workspaceCaption.textContent = `Режим: ${workspaceNames[mode]}`;\n        [...els.workspaceTabs.querySelectorAll('[data-workspace]')].forEach(button => {\n          const active = button.dataset.workspace === mode;\n          button.classList.toggle('is-active', active);\n          button.setAttribute('aria-current', active ? 'page' : 'false');\n        });\n        closeContextMenu();\n        cancelMapAction();\n        renderWorkspace();\n      }\n\n      function programTemplate() {\n        return `\n          <div class=\"panel-scroll\">\n            <div class=\"mode-summary\">\n              <span class=\"mode-summary__badge\">Программа</span>\n              <span>Дорожки, шаги, действия, условия, повторы и привязки к карте.</span>\n            </div>\n            <section class=\"section\"");
